### With Federation

```typescript
import {
  FederationGateway,
  FederatedAgentRegistry,
  FederatedMessageRouter,
} from '@anthropic/multi-agent-protocol/server/federation';

const gateway = new FederationGateway({
  systemId: 'system-a',
  buffer: { maxMessages: 10000 },
});

// Connect to peer
await gateway.connectPeer({
  systemId: 'system-b',
  endpoint: 'wss://system-b.example.com/federation',
