## Client SDK Interface

### Creating ACP Streams

```typescript
// Extend ClientConnection
class ClientConnection {
  /**
   * Create a virtual ACP stream connection to a specific agent.
   * Multiple ACP streams can coexist over a single MAP connection.
   */
  createACPStream(options: ACPStreamOptions): ACPStreamConnection;
}

interface ACPStreamOptions {
  /** Target agent that will handle ACP requests */
  targetAgent: AgentId;

  /** Client-side handlers for agent→client requests */
  client: ACPClientHandlers;

  /** Optional: receive MAP events alongside ACP (for observability) */
  exposeMapEvents?: boolean;
}

interface ACPClientHandlers {
  // Required
  requestPermission(params: ACP.RequestPermissionRequest): Promise<ACP.RequestPermissionResponse>;
  sessionUpdate(params: ACP.SessionNotification): Promise<void>;

  // Optional (based on advertised capabilities)
  readTextFile?(params: ACP.ReadTextFileRequest): Promise<ACP.ReadTextFileResponse>;
  writeTextFile?(params: ACP.WriteTextFileRequest): Promise<ACP.WriteTextFileResponse>;
  createTerminal?(params: ACP.CreateTerminalRequest): Promise<ACP.CreateTerminalResponse>;
  terminalOutput?(params: ACP.TerminalOutputRequest): Promise<ACP.TerminalOutputResponse>;
  releaseTerminal?(params: ACP.ReleaseTerminalRequest): Promise<ACP.ReleaseTerminalResponse>;
  waitForTerminalExit?(params: ACP.WaitForTerminalExitRequest): Promise<ACP.WaitForTerminalExitResponse>;
  killTerminal?(params: ACP.KillTerminalCommandRequest): Promise<ACP.KillTerminalCommandResponse>;
}
```

### ACPStreamConnection Interface

```typescript
/**
 * Virtual ACP connection over MAP.
 * Implements the full ACP Agent interface.
 */
class ACPStreamConnection {
  /** Unique identifier for this stream */
  readonly streamId: string;

  /** Target agent this stream connects to */
  readonly targetAgent: AgentId;

  /** Current ACP session ID (null until newSession called) */
  readonly sessionId: string | null;

  /** Whether initialize() has been called */
  readonly initialized: boolean;

  /** Agent capabilities from initialize response */
  readonly capabilities: ACP.AgentCapabilities | null;

  // ===== ACP Lifecycle Methods =====

  initialize(params: ACP.InitializeRequest): Promise<ACP.InitializeResponse>;
  authenticate(params: ACP.AuthenticateRequest): Promise<ACP.AuthenticateResponse>;

  // ===== ACP Session Methods =====

  newSession(params: ACP.NewSessionRequest): Promise<ACP.NewSessionResponse>;
  loadSession(params: ACP.LoadSessionRequest): Promise<ACP.LoadSessionResponse>;
  setSessionMode(params: ACP.SetSessionModeRequest): Promise<ACP.SetSessionModeResponse>;

  // ===== ACP Prompt Methods =====

  prompt(params: ACP.PromptRequest): Promise<ACP.PromptResponse>;
  cancel(params: ACP.CancelNotification): Promise<void>;

  // ===== MAP Observability (optional) =====

  /** Subscribe to MAP events from the target agent (if exposeMapEvents enabled) */
  onMapEvent?(handler: (event: MAPEvent) => void): () => void;

  // ===== Lifecycle =====

  /** Close this ACP stream and clean up resources */
  close(): Promise<void>;

  // ===== Events =====

  /** Emitted when ACP session is lost after reconnection */
  on(event: 'sessionLost', handler: (info: { sessionId: string }) => void): void;
}
```

### Usage Example

```typescript
// Connect to MAP system
const mapClient = await ClientConnection.connect('ws://localhost:8080', {
  name: 'MyIDE'
});

// Discover ACP-capable agents
const { agents } = await mapClient.listAgents();
const acpAgents = agents.filter(a => a.capabilities?.protocols?.includes('acp'));

// Create virtual ACP stream to a specific agent
const acp = mapClient.createACPStream({
  targetAgent: acpAgents[0].id,
  client: {
    requestPermission: async (req) => {
      const allowed = await showPermissionDialog(req.toolCall);
      return { outcome: allowed ? 'allowed' : 'denied' };
    },
    sessionUpdate: async (update) => {
      renderUpdate(update);
    },
    readTextFile: async (req) => {
      const content = await fs.readFile(req.path, 'utf-8');
      return { content };
    },
    createTerminal: async (req) => {
      const terminal = await ide.createTerminal(req.command);
      return { terminalId: terminal.id };
    }
  }
});

// Handle session loss on reconnection
acp.on('sessionLost', async ({ sessionId }) => {
  console.log('Session lost, attempting reload...');
  await acp.loadSession({ sessionId });
});

// Standard ACP workflow
const initResult = await acp.initialize({
  protocolVersion: '2024-10-07',
  clientInfo: { name: 'MyIDE', version: '1.0.0' },
  capabilities: {
    fs: { readTextFile: true, writeTextFile: true },
    terminal: true
  }
});

const { sessionId } = await acp.newSession({
  workingDirectory: '/path/to/project'
});

// Prompt with streaming via sessionUpdate handler
const result = await acp.prompt({
  sessionId,
  messages: [{
    role: 'user',
    content: [{ type: 'text', text: 'Fix the authentication bug' }]
  }]
});

console.log('Stop reason:', result.stopReason);

// Can create multiple streams to different agents
const acp2 = mapClient.createACPStream({
  targetAgent: 'research-agent-1',
  client: { /* handlers */ }
});

// Clean up
await acp.close();
await acp2.close();
await mapClient.disconnect();
```

