## Part 1: AgenticMeshTransport

### Stream Adapter

Create a stream adapter that converts agentic-mesh's `TunnelStream` to MAP SDK's `Stream` interface.

**File:** `ts-sdk/src/stream/agentic-mesh.ts`

```typescript
import type { Stream, AnyMessage } from './index';

// Types from agentic-mesh (peer dependency)
import type { 
  TunnelStream,
  TransportAdapter, 
  PeerEndpoint,
} from 'agentic-mesh';

/**
 * Configuration for agentic-mesh stream.
 */
export interface AgenticMeshStreamConfig {
  /** The agentic-mesh transport adapter (Nebula, Tailscale, etc.) */
  transport: TransportAdapter;

  /** Remote peer to connect to */
  peer: PeerEndpoint;

  /** Local peer ID for identification */
  localPeerId: string;

  /** Connection timeout in milliseconds (default: 10000) */
  timeout?: number;
}

/**
 * Creates a MAP Stream over an agentic-mesh tunnel.
 * 
 * This wraps agentic-mesh's TunnelStream (NDJSON over encrypted transport)
 * and adapts it to the MAP SDK's Stream interface.
 * 
 * @example
 * ```typescript
 * import { createNebulaTransport } from 'agentic-mesh';
 * import { agenticMeshStream } from '@anthropic/multi-agent-protocol';
 * 
 * const transport = createNebulaTransport({
 *   configPath: '/etc/nebula/config.yml',
 * });
 * 
 * const stream = await agenticMeshStream({
 *   transport,
 *   peer: { id: 'server', nebulaIp: '10.0.0.1', port: 4242 },
 *   localPeerId: 'my-client',
 * });
 * 
 * const client = new ClientConnection(stream, { name: 'MeshClient' });
 * await client.connect();
 * ```
 */
export async function agenticMeshStream(
  config: AgenticMeshStreamConfig
): Promise<Stream> {
  const { TunnelStream } = await import('agentic-mesh');

  // Start transport if needed
  if (!config.transport.active) {
    await config.transport.start();
  }

  // Connect to peer
  const connected = await config.transport.connect(config.peer);
  if (!connected) {
    throw new Error(`Failed to connect to peer: ${config.peer.id}`);
  }

  // Create tunnel stream
  const tunnelStream = new TunnelStream({
    transport: config.transport,
    peerId: config.peer.id,
    streamId: `map-${config.localPeerId}-${Date.now()}`,
  });

  await tunnelStream.open();

  // Adapt to MAP Stream interface
  return tunnelStreamToMapStream(tunnelStream);
}

/**
 * Adapts a TunnelStream to the MAP SDK Stream interface.
 */
function tunnelStreamToMapStream(tunnel: TunnelStream): Stream {
  const readable = new ReadableStream<AnyMessage>({
    async start(controller) {
      try {
        for await (const frame of tunnel) {
          controller.enqueue(frame as AnyMessage);
        }
        controller.close();
      } catch (error) {
        controller.error(error);
      }
    },
  });

  const writable = new WritableStream<AnyMessage>({
    async write(message) {
      await tunnel.write(message);
    },
    async close() {
      await tunnel.close();
    },
    abort(reason) {
      tunnel.close().catch(() => {});
    },
  });

  return { readable, writable };
}
```

### Static Factory Methods

Add convenience methods to `ClientConnection` and `AgentConnection` for mesh connections.

**File:** `ts-sdk/src/connection/client.ts` (additions)

```typescript
/**
 * Options for connecting via agentic-mesh transport.
 */
export interface MeshConnectOptions extends ClientConnectOptions {
  /** The agentic-mesh transport adapter */
  transport: TransportAdapter;

  /** Remote peer endpoint */
  peer: PeerEndpoint;

  /** Local peer ID */
  localPeerId: string;
}

class ClientConnection {
  // ... existing code ...

  /**
   * Connect to a MAP server via agentic-mesh transport.
   * 
   * @example
   * ```typescript
   * import { createNebulaTransport } from 'agentic-mesh';
   * 
   * const transport = createNebulaTransport({ configPath: '...' });
   * 
   * const client = await ClientConnection.connectMesh({
   *   transport,
   *   peer: { id: 'server', nebulaIp: '10.0.0.1', port: 4242 },
   *   localPeerId: 'dashboard',
   *   name: 'Dashboard',
   *   reconnection: true,
   * });
   * ```
   */
  static async connectMesh(options: MeshConnectOptions): Promise<ClientConnection> {
    const { agenticMeshStream } = await import('../stream/agentic-mesh');

    const stream = await agenticMeshStream({
      transport: options.transport,
      peer: options.peer,
      localPeerId: options.localPeerId,
      timeout: options.connectTimeout,
    });

    // Configure createStream for reconnection
    const createStream = async () => {
      return agenticMeshStream({
        transport: options.transport,
        peer: options.peer,
        localPeerId: options.localPeerId,
        timeout: options.connectTimeout,
      });
    };

    const reconnection = options.reconnection === true
      ? { enabled: true }
      : typeof options.reconnection === 'object'
        ? options.reconnection
        : undefined;

    const client = new ClientConnection(stream, {
      name: options.name,
      capabilities: options.capabilities,
      createStream,
      reconnection,
    });

    await client.connect({ auth: options.auth });

    return client;
  }
}
```

Similar addition for `AgentConnection.connectMesh()`.

