## Part 2: Git Sync Integration

### GitSyncCapability

Provide git sync as an optional capability that can be attached to connections.

**File:** `ts-sdk/src/git/sync.ts`

```typescript
import type { AgentConnection } from '../connection/agent';

// Types from agentic-mesh
import type { 
  GitSyncClient,
  SyncOptions,
  SyncResult,
  CloneOptions,
  PullOptions,
  PushOptions,
  TransportAdapter,
} from 'agentic-mesh';

/**
 * Configuration for git sync capability.
 */
export interface GitSyncConfig {
  /** The mesh transport to use for git operations */
  transport: TransportAdapter;

  /** Local repository path */
  repoPath: string;

  /** HTTP port for git helper (default: 3456) */
  httpPort?: number;
}

/**
 * Git sync capability for MAP agents.
 * 
 * Allows agents to synchronize repositories with peers over MAP.
 * 
 * @example
 * ```typescript
 * // Attach git sync to an agent
 * const gitSync = await createGitSync({
 *   transport: meshTransport,
 *   repoPath: '/my/repo',
 * });
 * 
 * // Sync with another agent
 * const result = await gitSync.sync('peer-agent-id', {
 *   branch: 'main',
 *   bidirectional: true,
 * });
 * 
 * // Or individual operations
 * await gitSync.pull('peer-agent-id', 'main');
 * await gitSync.push('peer-agent-id', 'feature-branch');
 * ```
 */
export interface GitSync {
  /** Bidirectional sync with a peer */
  sync(peerId: string, options?: SyncOptions): Promise<SyncResult>;

  /** Pull from a peer */
  pull(peerId: string, branch?: string, options?: PullOptions): Promise<SyncResult>;

  /** Push to a peer */
  push(peerId: string, branch?: string, options?: PushOptions): Promise<SyncResult>;

  /** Clone from a peer */
  clone(peerId: string, destPath: string, options?: CloneOptions): Promise<void>;

  /** Stop the git sync service */
  stop(): Promise<void>;
}

/**
 * Creates a git sync capability.
 */
export async function createGitSync(config: GitSyncConfig): Promise<GitSync> {
  const { 
    GitTransportService, 
    createGitSyncClient,
  } = await import('agentic-mesh');

  // Create git transport service
  const gitService = new GitTransportService({
    httpPort: config.httpPort ?? 3456,
    git: {
      repoPath: config.repoPath,
    },
  });

  // Create peer sender that uses the transport
  const peerSender = {
    sendToPeer: async (peerId: string, message: unknown) => {
      const conn = config.transport.getConnection(peerId);
      if (!conn) throw new Error(`No connection to peer: ${peerId}`);
      await conn.sendGitMessage(message);
    },
    isConnected: (peerId: string) => config.transport.isConnected(peerId),
  };

  gitService.setPeerSender(peerSender);
  await gitService.start();

  // Create sync client
  const syncClient = createGitSyncClient(gitService, config.repoPath);

  return {
    sync: (peerId, options) => syncClient.sync(peerId, options),
    pull: (peerId, branch, options) => syncClient.pull(peerId, branch, options),
    push: (peerId, branch, options) => syncClient.push(peerId, branch, options),
    clone: (peerId, destPath, options) => syncClient.clone(peerId, destPath, options),
    stop: () => gitService.stop(),
  };
}
```

### MeshPeer Convenience Class

For users who want the full agentic-mesh experience (MAP + Git + transport management), provide a convenience wrapper.

**File:** `ts-sdk/src/mesh/peer.ts`

```typescript
import type { AgentConnection } from '../connection/agent';
import type { GitSync } from '../git/sync';
import type { TransportAdapter, PeerEndpoint, MeshPeerConfig } from 'agentic-mesh';

/**
 * Configuration for MAPMeshPeer.
 */
export interface MAPMeshPeerConfig {
  /** Unique peer ID */
  peerId: string;

  /** Display name */
  name?: string;

  /** Transport configuration */
  transport: {
    type: 'nebula' | 'tailscale' | 'headscale';
    config: Record<string, unknown>;
  };

  /** Git sync configuration (optional) */
  git?: {
    enabled: boolean;
    repoPath: string;
    httpPort?: number;
  };

  /** Initial peers to connect to */
  peers?: PeerEndpoint[];
}

/**
 * High-level mesh peer for MAP agents.
 * 
 * Combines transport management, MAP connection, and git sync
 * into a single convenient interface.
 * 
 * @example
 * ```typescript
 * const peer = await MAPMeshPeer.create({
 *   peerId: 'worker-1',
 *   name: 'DataProcessor',
 *   transport: {
 *     type: 'nebula',
 *     config: { configPath: '/etc/nebula/config.yml' },
 *   },
 *   git: {
 *     enabled: true,
 *     repoPath: '/workspace',
 *   },
 *   peers: [
 *     { id: 'server', nebulaIp: '10.0.0.1', port: 4242 },
 *   ],
 * });
 * 
 * // Register as MAP agent
 * const agent = await peer.registerAgent({
 *   role: 'processor',
 * });
 * 
 * // Sync code with another peer
 * await peer.git.sync('worker-2', { branch: 'main' });
 * 
 * // Handle messages
 * agent.onMessage(async (msg) => {
 *   // Process...
 * });
 * ```
 */
export class MAPMeshPeer {
  readonly peerId: string;
  readonly transport: TransportAdapter;
  readonly git: GitSync | null;

  private constructor(
    peerId: string,
    transport: TransportAdapter,
    git: GitSync | null,
  ) {
    this.peerId = peerId;
    this.transport = transport;
    this.git = git;
  }

  static async create(config: MAPMeshPeerConfig): Promise<MAPMeshPeer> {
    const { createMeshPeer } = await import('agentic-mesh');

    // Create agentic-mesh peer (handles transport + git internally)
    const meshPeer = createMeshPeer({
      peerId: config.peerId,
      peerName: config.name,
      transport: config.transport,
      git: config.git,
      peers: config.peers,
    });

    await meshPeer.start();

    return new MAPMeshPeer(
      config.peerId,
      meshPeer.transport,
      meshPeer.git ?? null,
    );
  }

  /**
   * Register a MAP agent over this mesh peer's transport.
   */
  async registerAgent(options: {
    role?: string;
    name?: string;
    serverPeerId: string;
  }): Promise<AgentConnection> {
    const { AgentConnection } = await import('../connection/agent');

    return AgentConnection.connectMesh({
      transport: this.transport,
      peer: { id: options.serverPeerId } as PeerEndpoint,
      localPeerId: this.peerId,
      name: options.name ?? this.peerId,
      role: options.role,
      reconnection: true,
    });
  }

  /**
   * Stop the mesh peer and all services.
   */
  async stop(): Promise<void> {
    if (this.git) {
      await this.git.stop();
    }
    await this.transport.stop();
  }
}
```

