## Usage Examples

### Example 1: Client over Nebula Mesh

```typescript
import { ClientConnection } from '@anthropic/multi-agent-protocol';
import { createNebulaTransport } from 'agentic-mesh';

// Create Nebula transport
const transport = createNebulaTransport({
  configPath: '/etc/nebula/config.yml',
  certPath: '/etc/nebula/host.crt',
  keyPath: '/etc/nebula/host.key',
});

// Connect client over mesh
const client = await ClientConnection.connectMesh({
  transport,
  peer: { id: 'map-server', nebulaIp: '10.0.0.1', port: 4242 },
  localPeerId: 'dashboard-1',
  name: 'Dashboard',
  reconnection: true,
});

// Use as normal MAP client
const agents = await client.listAgents();
const sub = await client.subscribe({ eventTypes: ['agent.registered'] });
```

### Example 2: Agent with Git Sync

```typescript
import { MAPMeshPeer } from '@anthropic/multi-agent-protocol/mesh';

// Create mesh peer with git enabled
const peer = await MAPMeshPeer.create({
  peerId: 'worker-1',
  name: 'CodeProcessor',
  transport: {
    type: 'tailscale',
    config: { authKey: process.env.TAILSCALE_AUTH_KEY },
  },
  git: {
    enabled: true,
    repoPath: '/workspace/project',
  },
});

// Register as MAP agent
const agent = await peer.registerAgent({
  serverPeerId: 'coordinator',
  role: 'processor',
});

// Pull latest code from another worker
await peer.git!.pull('worker-2', 'main');

// Process work...
agent.onMessage(async (msg) => {
  await agent.busy();
  // Do work...

  // Push results
  await peer.git!.push('worker-2', 'results');
  await agent.idle();
});
```

### Example 3: Standard Git CLI (via mesh://)

```bash
# With git-remote-mesh in PATH (from agentic-mesh)
git remote add worker-2 mesh://worker-2-id/
git fetch worker-2
git merge worker-2/main
git push worker-2 feature-branch
```

