## Pattern: Graceful Degradation

All mail integration should degrade gracefully when mail is not supported:

```typescript
class TaskOrchestrator {
  #agent: AgentConnection;
  #mailEnabled: boolean;

  async initialize() {
    const result = await this.#agent.connect({ 
      agentId: 'orchestrator',
      capabilities: { mail: { canCreate: true } }
    });
    this.#mailEnabled = !!result.capabilities?.mail?.enabled;
  }

  async executeTask(task: string) {
    // Create conversation if mail available
    let convId: string | undefined;
    if (this.#mailEnabled) {
      const conv = await this.#agent.request('mail/create', {
        type: 'agent-task',
        subject: task,
      });
      convId = conv.conversation.id;
    }

    // Send task - works with or without mail
    await this.#agent.send(
      { agent: 'worker' },
      { task },
      convId ? { mail: { conversationId: convId } } : undefined
    );
  }
}
```

